WITH recent_suppliers AS (SELECT * FROM suppliers WHERE city IN ('Chiang Mai', 'London') AND city NOT IN ('Singapore', 'Bangkok', 'London')), CountrySummary AS (SELECT country, SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END) AS us_count, ROUND(STDDEV(rating), 2) AS stddev_rating FROM recent_suppliers GROUP BY country) SELECT * FROM CountrySummary ORDER BY stddev_rating DESC, us_count DESC;
